"""Read-only final CAPS guard preflight; does not call main or allocate GPU."""
from pathlib import Path
import base64,hashlib,importlib.util,json,time,types
encoded=''
g=types.ModuleType('caps_guard_readonly');exec(compile(base64.b64decode(encoded),'caps_guard_readonly','exec'),g.__dict__)
g.require_final_bindings()
spec=importlib.util.spec_from_file_location('caps_host_preflight',g.HOST);h=importlib.util.module_from_spec(spec);spec.loader.exec_module(h)
g.verify_previous_owner();identity=g.validate_train_inputs(h)
immutable={}
for phase in g.PREVIOUS_ATTEMPTED_PHASES:
 # Acquisition immutable aliases are checked here for evidence, without scoring quality.
 actual=h.tree_hashes(g.PREVIOUS_ROOT/phase);expected=h.read(g.PREVIOUS_ROOT/(phase+'_immutable.sha256.json'));assert actual==expected
 immutable[phase]={'files':len(actual),'map_sha256':h.sha(g.PREVIOUS_ROOT/(phase+'_immutable.sha256.json')),'unchanged':True}
receipt=h.read(g.PREVIOUS_ROOT/'train/training_receipt.json');stop=h.read(g.PREVIOUS_ROOT/'final_stop/stop_diagnostics.json')
print(json.dumps({'read_only':True,'checked_unix':time.time(),'guard_runtime_sha256':hashlib.sha256(base64.b64decode(encoded)).hexdigest(),'identity':identity,'successful_smoke_admission':True,'terminal_curriculum_ownership_checked':True,'curriculum_immutable_aliases':immutable,'curriculum_quality_used_as_admission':False,'curriculum_updates':receipt['updates_completed'],'curriculum_strict_reload':receipt['reload'],'curriculum_wall_seconds':receipt['wall_seconds'],'curriculum_quiet_passed_replicas':sum(r['quiet']['pass'] for c in stop['scenarios'] for r in c['replicas']),'exact_owned_identifiers_absent':{'smoke':8,'curriculum':12},'dispatch_performed':False},indent=2))
